-- Consent forms: the emails become letters on the school's letterhead (HTML, inline styles): the code in a
-- box, the new form and the reminder with an "Answer the form" button and the link, the decision. A
-- template the school has already reworded is left as it is.
UPDATE comms_templates SET body = '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#00265D">Your one-time code</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">Use this code to open the form &quot;{{form}}&quot;.</p></td></tr><tr><td align="center" style="padding:16px 24px"><div style="display:inline-block;font-size:32px;letter-spacing:8px;font-weight:700;color:#0B1F3A;background:#E6F6FA;border:1px solid #B8E4EF;border-radius:8px;padding:14px 24px">{{otp}}</div><div style="color:#5B6676;font-size:13px;margin-top:10px">Valid for {{minutes}} minutes. Do not share it with anyone.</div></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">If you did not ask for this code, ignore this email.</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', format = 'html', updated_at = now()
 WHERE code = 'consent_otp' AND channel = 'email' AND format = 'text' AND body LIKE '{{otp}} is your one-time code%';
UPDATE comms_templates SET body = '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#00265D">A form waits for your answer</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">{{school}} asks you to answer the form &quot;{{form_title}}&quot;{{closes_on}}.</p></td></tr><tr><td style="padding:16px 24px 8px"><a href="{{link}}" style="display:inline-block;background:#00265D;color:#FFFFFF;text-decoration:none;font-weight:600;font-size:15px;padding:12px 22px;border-radius:6px">Answer the form</a><div style="color:#5B6676;font-size:12px;margin-top:10px;word-break:break-all">Or open: {{link}}</div></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">You can also answer it in the EduPro parent app under Consent forms.</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', format = 'html', updated_at = now()
 WHERE code = 'consent_form_new' AND channel = 'email' AND format = 'text' AND body LIKE '{{school}} asks you to answer%';
UPDATE comms_templates SET body = '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#B45309">Reminder: please answer</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">The form &quot;{{form_title}}&quot; of {{school}} still waits for your answer{{closes_on}}.</p></td></tr><tr><td style="padding:16px 24px 8px"><a href="{{link}}" style="display:inline-block;background:#00265D;color:#FFFFFF;text-decoration:none;font-weight:600;font-size:15px;padding:12px 22px;border-radius:6px">Answer the form</a><div style="color:#5B6676;font-size:12px;margin-top:10px;word-break:break-all">Or open: {{link}}</div></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">If you have already answered, please ignore this reminder.</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', format = 'html', updated_at = now()
 WHERE code = 'consent_form_reminder' AND channel = 'email' AND format = 'text' AND body LIKE 'Reminder: the form%';
UPDATE comms_templates SET body = '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#00265D">Your answer {{number}}</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">Your answer to &quot;{{form}}&quot; is <strong>{{decision}}</strong>.</p></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">{{note}}</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', format = 'html', updated_at = now()
 WHERE code = 'consent_decision' AND channel = 'email' AND format = 'text' AND body LIKE 'Your answer {{number}}%';

-- new schools get the letters at once
CREATE OR REPLACE FUNCTION app.consent_seed_templates(p_school BIGINT) RETURNS VOID LANGUAGE sql AS $fn$
  INSERT INTO comms_templates (school_id, code, channel, name, subject, body, variables, category, format)
  SELECT p_school, t.code, ch.channel::comms_channel, t.name,
         CASE WHEN ch.channel = 'email' THEN t.subject END,
         CASE WHEN ch.channel = 'email' THEN t.html ELSE t.body END, t.variables::jsonb, 'service',
         CASE WHEN ch.channel = 'email' THEN 'html' ELSE 'text' END
    FROM (VALUES
      ('consent_otp', 'Consent form: one-time code', 'Your code for {{school}}',
       '{{otp}} is your one-time code for the form "{{form}}" of {{school}}. It is valid for {{minutes}} minutes. Do not share it.',
       '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#00265D">Your one-time code</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">Use this code to open the form &quot;{{form}}&quot;.</p></td></tr><tr><td align="center" style="padding:16px 24px"><div style="display:inline-block;font-size:32px;letter-spacing:8px;font-weight:700;color:#0B1F3A;background:#E6F6FA;border:1px solid #B8E4EF;border-radius:8px;padding:14px 24px">{{otp}}</div><div style="color:#5B6676;font-size:13px;margin-top:10px">Valid for {{minutes}} minutes. Do not share it with anyone.</div></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">If you did not ask for this code, ignore this email.</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', '["otp","form","school","minutes"]'),
      ('consent_decision', 'Consent form: decision', '{{form}}: your answer {{number}}',
       'Your answer {{number}} to "{{form}}" is {{decision}}. {{note}} - {{school}}',
       '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#00265D">Your answer {{number}}</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">Your answer to &quot;{{form}}&quot; is <strong>{{decision}}</strong>.</p></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">{{note}}</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', '["form","number","decision","note","school"]'),
      ('consent_form_new', 'Consent form: please answer', '{{form_title}}: please answer',
       '{{school}} asks you to answer the form "{{form_title}}"{{closes_on}}. Please answer it in the EduPro app or here: {{link}}',
       '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#00265D">A form waits for your answer</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">{{school}} asks you to answer the form &quot;{{form_title}}&quot;{{closes_on}}.</p></td></tr><tr><td style="padding:16px 24px 8px"><a href="{{link}}" style="display:inline-block;background:#00265D;color:#FFFFFF;text-decoration:none;font-weight:600;font-size:15px;padding:12px 22px;border-radius:6px">Answer the form</a><div style="color:#5B6676;font-size:12px;margin-top:10px;word-break:break-all">Or open: {{link}}</div></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">You can also answer it in the EduPro parent app under Consent forms.</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', '["school","form_title","closes_on","link"]'),
      ('consent_form_reminder', 'Consent form: reminder', 'Reminder: {{form_title}}',
       'Reminder: the form "{{form_title}}" of {{school}} still waits for your answer{{closes_on}}. Answer it in the EduPro app or here: {{link}}',
       '<!doctype html><html><body style="margin:0;padding:0;background:#F3F5F9"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F5F9;padding:24px 0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border-radius:10px;overflow:hidden;font-family:Segoe UI,Arial,Helvetica,sans-serif"><tr><td style="background:#00265D;color:#FFFFFF;padding:16px 24px;font-size:16px;font-weight:600">{{school}}</td></tr><tr><td style="padding:24px 24px 8px"><div style="font-size:20px;font-weight:700;color:#B45309">Reminder: please answer</div><p style="margin:10px 0 0;color:#2B3545;font-size:15px;line-height:1.5">The form &quot;{{form_title}}&quot; of {{school}} still waits for your answer{{closes_on}}.</p></td></tr><tr><td style="padding:16px 24px 8px"><a href="{{link}}" style="display:inline-block;background:#00265D;color:#FFFFFF;text-decoration:none;font-weight:600;font-size:15px;padding:12px 22px;border-radius:6px">Answer the form</a><div style="color:#5B6676;font-size:12px;margin-top:10px;word-break:break-all">Or open: {{link}}</div></td></tr><tr><td style="padding:8px 24px 4px;color:#2B3545;font-size:14px;line-height:1.5">If you have already answered, please ignore this reminder.</td></tr><tr><td style="padding:16px 24px 22px;color:#8791A0;font-size:12px;line-height:1.5">This is an automatic message from {{school}}. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', '["school","form_title","closes_on","link"]')
    ) AS t(code, name, subject, body, html, variables)
    CROSS JOIN (VALUES ('sms'), ('whatsapp'), ('email')) AS ch(channel)
  ON CONFLICT (school_id, code, channel) DO NOTHING
$fn$;
